#ifndef MODBUS_PERSISTENCE_H
#define MODBUS_PERSISTENCE_H

#include <stdbool.h>
#include <stdint.h>

#include "modbus_engine_config.h"
#include "modbus_module.h"

/* The payload is generated by enumerating canonical PERSISTENT rows. */
#define MODBUS_PERSISTENCE_MAGIC          0x50584346UL
#define MODBUS_PERSISTENCE_FORMAT_VERSION 1U
#define MODBUS_PERSISTENCE_COMMIT_MARKER  0x434F4D4DUL
#define MODBUS_PERSISTENCE_MAX_WORDS      256U

typedef struct {
    uint16_t word_count;
    uint16_t words[MODBUS_PERSISTENCE_MAX_WORDS];
} modbus_persistent_payload_t;

typedef struct {
    uint32_t magic;
    uint16_t format_version;
    uint16_t payload_length;
    uint32_t sequence;
    modbus_persistent_payload_t payload;
    uint32_t crc32;
} modbus_persistent_record_t;

typedef enum {
    MODBUS_PERSISTENCE_OK = 0,
    MODBUS_PERSISTENCE_INVALID_ARGUMENT,
    MODBUS_PERSISTENCE_NO_VALID_RECORD,
    MODBUS_PERSISTENCE_STORAGE_ERROR,
    MODBUS_PERSISTENCE_VERIFY_ERROR,
    MODBUS_PERSISTENCE_INVALID_PAYLOAD,
    MODBUS_PERSISTENCE_UNCHANGED
} modbus_persistence_status_t;

void ModbusPersistence_BindHoldingStorage(uint16_t *holding_storage,
                                          uint16_t holding_word_count);
bool ModbusPersistence_BuildShadow(modbus_persistent_payload_t *out_payload);
bool ModbusPersistence_ApplyShadow(const modbus_persistent_payload_t *payload);

/* Compatibility boundary used by the existing configuration module. */
bool ModbusPersistence_LoadConfig(ModbusConfig_t *out_config);
bool ModbusPersistence_SaveConfig(const ModbusConfig_t *config);
/* Persist a complete canonical-default shadow without reading live RAM. */
bool ModbusPersistence_SaveFactoryDefaults(const ModbusConfig_t *config);
/* Permanently prevent the pre-H1 single-key record from being migrated. */
bool ModbusPersistence_BlockLegacyConfig(void);
bool ModbusPersistence_IsLegacyConfigBlocked(void);

bool ModbusPersistence_IsDirty(void);
bool ModbusPersistence_HasVerifiedRecord(void);
uint32_t ModbusPersistence_GetVerifiedSequence(void);
modbus_persistence_status_t ModbusPersistence_GetLastStatus(void);

#if MODBUS_G_TEST_HOOKS

typedef enum {
    MODBUS_PERSIST_TEST_SUCCESS = 0,
    MODBUS_PERSIST_TEST_ERASE_FAIL,
    MODBUS_PERSIST_TEST_WRITE_FAIL,
    MODBUS_PERSIST_TEST_VERIFY_FAIL,
    MODBUS_PERSIST_TEST_COMMIT_FAIL,
    MODBUS_PERSIST_TEST_INVALID_STORED_DATA,
    MODBUS_PERSIST_TEST_CORRUPT_CRC,
    MODBUS_PERSIST_TEST_INVALID_VERSION,
    MODBUS_PERSIST_TEST_POWER_LOSS,
    MODBUS_PERSIST_TEST_LEGACY_BLOCK_FAIL
} modbus_persistence_test_result_t;

void ModbusPersistence_TestReset(void);
void ModbusPersistence_TestSetResult(modbus_persistence_test_result_t result);
bool ModbusPersistence_TestSetStoredConfig(const ModbusConfig_t *config);
bool ModbusPersistence_TestGetStoredConfig(ModbusConfig_t *out_config);
uint32_t ModbusPersistence_TestGetSaveCount(void);
bool ModbusPersistence_TestSimulateBoot(ModbusConfig_t *loaded_config);
bool ModbusPersistence_TestGetSlot(uint8_t slot,
                                   modbus_persistent_record_t *record);
bool ModbusPersistence_TestSetSlot(uint8_t slot,
                                   const modbus_persistent_record_t *record,
                                   bool committed);

#endif

#endif
